use super::*;
use crate::{java_runtime::{Rc,RefCell},cn::wps::et::ss::formula::ptg::Ptg::{PtgArray,PtgRef}};
use serde_json::{Value,json};use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
pub(crate) fn token(t:Option<&PtgRef>)->Value{let Some(t)=t else{return Value::Null;};let t=t.borrow();let mut o=json!({"class":t.javaClassName(),"sid":t.getSid(),"ptgClass":t.getPtgClass(),"text":call(||t.toString()),"bytes":call(||{let _size=t.getSize();let mut b=vec![];t.write(&mut b);b.iter().map(|b|format!("{b:02x}")).collect::<String>()})});match t.kind{PtgKind::Ref{..}|PtgKind::Ref3D{..}|PtgKind::Ref3DExt{..}=>o["coordinates"]=json!([t.getRow(),t.getColumn(),t.isRowRelative(),t.isColRelative()]),PtgKind::Area{..}|PtgKind::Area3D{..}|PtgKind::Area3DExt{..}=>o["coordinates"]=json!([t.getFirstRow(),t.getLastRow(),t.getFirstColumn(),t.getLastColumn(),t.isFirstRowRelative(),t.isLastRowRelative(),t.isFirstColRelative(),t.isLastColRelative()]),_=>{}}match t.kind{PtgKind::Ref3D{extern_index,..}|PtgKind::Area3D{extern_index,..}=>o["extern"]=json!(extern_index),_=>{}}o}
pub(crate) fn tokens(p:&PtgArray)->Value{json!(p.borrow().iter().map(|t|token(t.as_ref())).collect::<Vec<_>>())}
fn one(p:&Value)->Value{let read=if p["inputVersion"]==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007};let sv=if p["version"].is_null(){None}else{Some(if p["version"]==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007})};let b=p["bytes"].as_str().unwrap();let b:Vec<u8>=(0..b.len()).step_by(2).map(|i|u8::from_str_radix(&b[i..i+2],16).unwrap()).collect();let mut initial=Ptg::readTokens__stream__array(p["size"].as_i64().unwrap()as i32,&b,p["external"]==true,read);if let Some(row)=p["setRow"].as_i64(){initial.borrow()[0].as_ref().unwrap().borrow_mut().setRow(row as i32);}if p["duplicate"]==true&&!initial.borrow().is_empty(){let t=initial.borrow()[0].clone();initial=Rc::new(RefCell::new(vec![t.clone(),t].into_boxed_slice()));}if p["nullToken"]==true{initial=Rc::new(RefCell::new(vec![None].into_boxed_slice()));}let input=if p["nullArray"]==true{None}else{Some(initial)};let mut out=json!({"before":input.as_ref().map(tokens)});let mut ret=None;out["call"]=call(||{let row=p["row"].as_i64().unwrap()as i32;let col=p["col"].as_i64().unwrap()as i32;ret=Some(if p["single"]==true{let t=input.as_ref().map(|a|a.borrow()[0].clone()).flatten();let t=FormulaHelper::replaceNPtg__reference(t.as_ref(),row,col,sv);Rc::new(RefCell::new(vec![Some(t)].into_boxed_slice()))}else{FormulaHelper::replaceNPtgs__array(input.as_ref(),row,col,sv)});});if let Some(ret)=ret{let identities:Vec<_>=ret.borrow().iter().map(|t|input.as_ref().map(|input|input.borrow().iter().map(|s|match(t,s){(Some(t),Some(s))=>Rc::ptr_eq(t,s),(None,None)=>true,_=>false}).collect::<Vec<_>>()).unwrap_or_default()).collect();out["ret"]=tokens(&ret);out["sameArray"]=json!(input.as_ref().is_some_and(|p|Rc::ptr_eq(p,&ret)));out["identities"]=json!(identities);if !ret.borrow().is_empty(){let t=ret.borrow()[0].clone();if let Some(t)=t{out["mutate"]=call(||t.borrow_mut().setClass(64));}}}out["after"]=input.as_ref().map(tokens).unwrap_or(Value::Null);out}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_reference_factories_and_replacement_arrays(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/replace-nptg-r0b72");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let actual=json!({"cases":input["cases"].as_array().unwrap().iter().map(one).collect::<Vec<_>>()});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
